#include <iostream>
#include <vector>

/* 砍一半：两头夹着找，每趟看正中间那一只，答「比了几次」；没找到答负数 */
int half_find(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    int tries = 0;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (a[mid] == target) {
            return tries;
        } else if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -tries;
}

int main() {
    int n = 0;
    std::cin >> n;
    int target = 0;
    std::cin >> target;
    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    int times = half_find(a, target);
    if (times < 0) {
        std::cout << "砍一半：没找到\n";
    } else {
        std::cout << "砍一半：比了 " << times << " 次\n";
    }
    return 0;
}
